using SoulsFormats;using System.Numerics;using System.Text.Json;
internal static class CatacombsFigureAudit {
    static string Leaf(string p)=>Path.GetFileName(p.Replace('\\','/'));
    static float[] V(Vector3 p)=>[p.X,p.Y,p.Z];
    internal static void Run(Func<string,byte[]?> source,Func<string,byte[]> export,string output){
        Directory.CreateDirectory(output);var materials=BND3.Read(source("mtd/Mtd.mtdbnd.dcx")!);var np=BND3.Read(source("param/GameParam/GameParam.parambnd.dcx")!);var result=new List<object>();var meshes=new List<object>();
        void Inspect(string name,FLVER2 model){var worlds=SkinRetarget.World(model.Nodes);result.Add(new{name,HeaderMin=V(model.Header.BoundingBoxMin),HeaderMax=V(model.Header.BoundingBoxMax),Meshes=model.Meshes.Select((m,i)=>new{Index=i,m.MaterialIndex,m.Dynamic,m.NodeIndex,m.BoneIndices,Vertices=m.Vertices.Count,Triangles=m.FaceSets.Sum(f=>f.Indices.Count/3),Material=model.Materials[m.MaterialIndex].Name,MTD=model.Materials[m.MaterialIndex].MTD,Mask=System.Text.RegularExpressions.Regex.Match(model.Materials[m.MaterialIndex].Name,@"#(\d+)#").Value}),Materials=model.Materials.Select(m=>new{m.Name,m.Index,m.MTD,Textures=m.Textures.Select(t=>new{t.ParamName,t.Path,t.TilingScale})})});foreach(var(m,index)in model.Meshes.Select((m,i)=>(m,i))){var vertices=m.Vertices.Select(v=>m.Dynamic==1?v.Position:m.BoneIndices.Count>0?Vector3.Transform(v.Position,worlds[SkinRetarget.Bone(m,v.BoneIndices[0])]):v.Position).Select(V).ToArray();meshes.Add(new{name,index,Material=model.Materials[m.MaterialIndex].Name,Vertices=vertices,Faces=m.FaceSets.Where(f=>f.Flags==FLVER2.FaceSet.FSFlags.None).SelectMany(f=>f.Triangulate(m.Vertices.Count<65535))});}}
        var character=MapCharacters.Authored(source,"c2900");Inspect("source-c2900",FLVER2.Read(character.Model));foreach(string model in new[]{"o3310","o3311","o3312","o3320","o3321"}){var bank=BND3.Read(source("obj/"+model+".objbnd.dcx")!);var f=FLVER2.Read(bank.Files.First(f=>Leaf(f.Name)==model+".flver").Bytes);Inspect("source-"+model,f);foreach(var m in f.Materials){var entries=materials.Files.Where(x=>Leaf(x.Name).Equals(Leaf(m.MTD),StringComparison.OrdinalIgnoreCase)).ToArray();foreach(var entry in entries){var definition=MTD.Read(entry.Bytes);File.WriteAllText(Path.Combine(output,model+"-"+Leaf(entry.Name)+".json"),JsonSerializer.Serialize(new{definition.Description,definition.ShaderPath,Params=definition.Params.Select(p=>new{p.Name,p.Type,p.Value}),Textures=definition.Textures.Select(t=>new{t.Type,t.Extended,t.UVNumber,t.Path,t.ShaderDataIndex})},new JsonSerializerOptions{WriteIndented=true}));}}}
        foreach(string model in new[]{"m070113","m070114","m070115","m070116","m070117"})Inspect("export-"+model,FLVER2.Read(export("map/m40_05_00_00/m40_05_00_00_"+model[1..]+".flver.dcx")));
        File.WriteAllText(Path.Combine(output,"models.json"),JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));File.WriteAllText(Path.Combine(output,"mesh-projections.json"),JsonSerializer.Serialize(meshes));Console.WriteLine("Source figure audit11models; no source/render masks modified");
    }
}
